<script setup lang="ts">
import { tx } from '@/i18n'
import { onMounted, reactive, ref } from 'vue'
import { agentDateLabel, agentStatusLabel, emptyAgentPage, formatMoney, useAgentApi, useAgentActions, type AgentWallet, type AgentTransaction, type AgentRecharge } from '../lib/agentWorkbench'
import AgentPagination from './AgentPagination.vue'
const api = useAgentApi(), balances = ref<AgentWallet[]>([]), transactions = ref(emptyAgentPage<AgentTransaction>()), recharges = ref(emptyAgentPage<AgentRecharge>())
const profile = reactive({ companyName: '', contactName: '' }), currency = ref('USD'), loading = ref(false)
const currencies = ['USD','CNY','EUR','GBP','HKD','JPY','CAD','AUD','SGD']
const form = reactive({ currencyCode: 'USD', amount: '', providerCode: 'bank_transfer', payerReference: '', proofReference: '' })
const { busy, error, success, run } = useAgentActions()
async function loadTransactions(page = 1) { try { transactions.value = await api.fetchTransactions(currency.value, page) } catch (e) { error.value = e instanceof Error ? e.message : tx('Unable to load wallet transactions.') } }
async function loadRecharges(page = 1) { try { recharges.value = await api.fetchRecharges(page) } catch (e) { error.value = e instanceof Error ? e.message : tx('Unable to load top-up history.') } }
async function load() { loading.value = true; try { const [company, wallets] = await Promise.all([api.fetchMerchantProfile(),api.fetchWallets()]); Object.assign(profile,company); balances.value = wallets; await Promise.all([loadTransactions(),loadRecharges()]) } catch (e) { error.value = e instanceof Error ? e.message : tx('Unable to load company balances.') } finally { loading.value = false } }
async function saveProfile() { const payload = { ...profile }; await run('profile:save',payload,() => api.saveMerchantProfile(payload),() => {},tx('Company profile saved.')) }
async function recharge() { const payload = { ...form }; if (await run('recharge:create',payload,key => api.requestRecharge(payload,key),() => { form.amount='';form.payerReference='';form.proofReference='' },tx('Top-up submitted. The balance will be credited after payment verification.'))) await loadRecharges() }
onMounted(load)
</script>
<template><section data-testid="agent-wallet-panel"><div class="agent-toolbar"><h2>{{ $tx('Company wallet') }}</h2><el-button :loading="loading" :disabled="busy" @click="load">{{ $tx('Refresh') }}</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="success" :title="success" type="success" :closable="false" /><div class="agent-wallet-balances"><article v-for="code in currencies" :key="code" class="agent-stock-card"><span>{{ code }}</span><strong>{{ formatMoney(balances.find(wallet => wallet.currencyCode === code)?.balance || 0,code) }}</strong></article></div><div class="form-grid"><form class="portal-form agent-operation" @submit.prevent="saveProfile"><h3>{{ $tx('Company profile') }}</h3><label>{{ $tx('Company name') }}<input v-model="profile.companyName" required maxlength="191" :disabled="busy" /></label><label>{{ $tx('Contact person') }}<input v-model="profile.contactName" required maxlength="128" :disabled="busy" /></label><button class="btn-primary" :disabled="busy">{{ $tx('Save profile') }}</button></form><form class="portal-form agent-operation" data-testid="agent-recharge-form" @submit.prevent="recharge"><h3>{{ $tx('Request top-up') }}</h3><p class="muted-copy">{{ $tx('Transfer funds using the payment details provided by NXR, then submit your payment reference for verification.') }}</p><fieldset :disabled="busy"><div class="form-grid"><label>{{ $tx('Currency') }}<select v-model="form.currencyCode"><option v-for="code in currencies" :key="code">{{ code }}</option></select></label><label>{{ $tx('Amount') }}<input v-model="form.amount" type="number" required :min="form.currencyCode === 'JPY' ? 1 : .01" :step="form.currencyCode === 'JPY' ? 1 : .01" max="99999999" /></label></div><label>{{ $tx('Transfer method') }}<select v-model="form.providerCode"><option value="bank_transfer">{{ $tx('Bank transfer') }}</option><option value="wechat_transfer">{{ $tx('WeChat transfer') }}</option><option value="alipay_transfer">{{ $tx('Alipay transfer') }}</option></select></label><label>{{ $tx('Transfer reference') }}<input v-model="form.payerReference" required maxlength="255" /></label><label>{{ $tx('Payment proof details (optional)') }}<input v-model="form.proofReference" maxlength="512" /></label></fieldset><button class="btn-primary" :disabled="busy" data-testid="agent-submit-recharge">{{ $tx('Submit for payment verification') }}</button></form></div><h3>{{ $tx('Top-up history') }}</h3><el-table :data="recharges.items" border><el-table-column prop="rechargeNo" :label="$tx('Top-up reference')" min-width="180" /><el-table-column :label="$tx('Amount')" min-width="130"><template #default="{row}">{{ formatMoney(row.amount,row.currencyCode) }}</template></el-table-column><el-table-column :label="$tx('Status')" min-width="130"><template #default="{row}">{{ agentStatusLabel(row.statusCode) }}</template></el-table-column><el-table-column prop="reviewNote" :label="$tx('Payment verification notes')" min-width="180" /><el-table-column :label="$tx('Time')" min-width="170"><template #default="{row}">{{ agentDateLabel(row.createdAt) }}</template></el-table-column></el-table><AgentPagination v-bind="recharges" :disabled="busy" @change="loadRecharges" /><div class="agent-toolbar"><h3>{{ $tx('Wallet transactions') }}</h3><el-select v-model="currency" style="width:130px" @change="loadTransactions()"><el-option v-for="code in currencies" :key="code" :value="code" :label="code" /></el-select></div><el-table :data="transactions.items" border><el-table-column :label="$tx('Time')" min-width="170"><template #default="{row}">{{ agentDateLabel(row.createdAt) }}</template></el-table-column><el-table-column :label="$tx('Amount')" min-width="130"><template #default="{row}">{{ row.directionCode === 'debit' ? '−' : '+' }}{{ formatMoney(row.amount,currency) }}</template></el-table-column><el-table-column :label="$tx('Balance')" min-width="130"><template #default="{row}">{{ formatMoney(row.balanceAfter,currency) }}</template></el-table-column><el-table-column prop="note" :label="$tx('Description')" min-width="220" /></el-table><AgentPagination v-bind="transactions" :disabled="busy" @change="loadTransactions" /></section></template>
